from collections import Counter
from pathlib import Path
import json
import sqlite3
import subprocess
import sys
import tempfile
import vault

columns = {'accounts': ('tenant','name','balance'), 'transfers': ('tenant','key','source','target','amount'), 'audit': ('tenant','key','source','target','amount')}
def state(path):
    with sqlite3.connect(path) as con:
        con.text_factory = bytes
        data = {table: Counter(con.execute('SELECT ' + ','.join('typeof('+c+'),'+c for c in names) + ' FROM '+table)) for table, names in columns.items()}
        schema = con.execute('SELECT type,name,sql FROM sqlite_master ORDER BY name').fetchall()
        return data, schema

def setup(path, sql=''):
    vault.init_db(path)
    with sqlite3.connect(path) as con:
        con.executescript(\"INSERT INTO accounts VALUES ('one','a',100),('one','b',0),('two','foreign',777); INSERT INTO audit VALUES ('two','history','old','target',7);\" + sql)

def pay(path):
    return vault.transfer(path, 'one', 'a', 'b', 10, 'k')

cases = {
    'erased_audit': \"CREATE TRIGGER bad AFTER INSERT ON audit BEGIN DELETE FROM audit WHERE rowid=NEW.rowid; END;\",
    'foreign_mutation': \"CREATE TRIGGER bad AFTER INSERT ON audit BEGIN UPDATE accounts SET balance=0 WHERE tenant='two'; END;\",
    'storage_type_change': \"CREATE TRIGGER bad AFTER INSERT ON audit BEGIN UPDATE accounts SET name=CAST(name AS BLOB) WHERE tenant='two'; END;\",
    'extra_unique_victims': \"\"\"
      INSERT INTO audit VALUES ('two','second','another','target',9);
      CREATE UNIQUE INDEX audit_key ON audit(key);
      CREATE UNIQUE INDEX audit_source ON audit(source);
      CREATE TRIGGER bad AFTER INSERT ON audit WHEN NEW.tenant='one' BEGIN
        INSERT OR REPLACE INTO audit VALUES ('two','history','another','target',7);
        UPDATE audit SET source='old' WHERE key='history';
      END;
    \"\"\",
    'harmless_raw_noop': \"\"\"
      UPDATE accounts SET balance=CAST(X'FF' AS TEXT) WHERE tenant='two';
      CREATE TRIGGER good AFTER INSERT ON audit BEGIN
        UPDATE accounts SET balance=balance, rowid=rowid+100 WHERE tenant='two';
        INSERT OR IGNORE INTO accounts VALUES ('two','foreign',0);
      END;
    \"\"\",
    'implicit_replace_counter_control': \"\"\"
      CREATE UNIQUE INDEX audit_key ON audit(key);
      CREATE TRIGGER explicit_deletes_fail BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT, 'explicit deletion'); END;
      CREATE TRIGGER good AFTER INSERT ON audit WHEN NEW.tenant='one' BEGIN
        INSERT OR REPLACE INTO audit VALUES ('two','history','old','target',7);
        SELECT CASE WHEN total_changes()"'!=4 THEN RAISE(ABORT,'"'counter changed') END;
      END;
    \"\"\",
}
with tempfile.TemporaryDirectory(prefix='.assessment-repairs-', dir=Path.cwd()) as folder:
    for label, sql in cases.items():
        path = Path(folder) / (label + '.sqlite')
        setup(path, sql)
        before, schema_before = state(path)
        try:
            result = pay(path)
            outcome = 'success'
        except Exception as error:
            outcome = type(error).__name__ + ': ' + str(error)
        after, schema_after = state(path)
        foreign_unchanged = all(Counter({r:n for r,n in before[t].items() if r[1]==b'two'}) == Counter({r:n for r,n in after[t].items() if r[1]==b'two'}) for t in columns)
        print(json.dumps({'case':label,'outcome':outcome,'all_rows_unchanged':before==after,'foreign_rows_unchanged':foreign_unchanged,'schema_unchanged':schema_before==schema_after}))
        if label in ('harmless_raw_noop','implicit_replace_counter_control'):
            assert outcome == 'success' and foreign_unchanged
            assert pay(path) == result and state(path)[0] == after
        else:
            assert outcome.startswith('IntegrityError:') and before == after
        assert schema_before == schema_after
    path = Path(folder) / 'cli_replay.sqlite'
    setup(path)
    before = state(path)
    payload = r'{\"op\":\"transfer\",\"tenant\":\"one\",\"source\":\"a\",\"target\":\"b\",\"amount\":1,\"\\u0061mount\":10,\"key\":\"k\"}'
    duplicate = subprocess.run([sys.executable,'-B','app.py',str(path),payload],capture_output=True,text=True,timeout=10)
    print(json.dumps({'case':'escaped_duplicate','exit':duplicate.returncode,'stdout':duplicate.stdout,'stderr':duplicate.stderr,'unchanged':state(path)==before}))
    assert (duplicate.returncode, duplicate.stdout, duplicate.stderr) == (2,'','{\"error\": \"invalid request\"}\\n') and state(path)==before
    receipt = pay(path)
    with sqlite3.connect(path) as con:
        con.execute(\"DELETE FROM accounts WHERE tenant='one'\")
    before = state(path)
    replay = subprocess.run([sys.executable,'-B','app.py',str(path),json.dumps({'op':'transfer',**receipt})],capture_output=True,text=True,timeout=10)
    assert replay.returncode == 0 and json.loads(replay.stdout)==receipt and state(path)==before
    outcomes = []
    for key, amount in [('new',10),('k',11)]:
        try:
            vault.transfer(path,'one','a','b',amount,key)
            outcomes.append('unexpected success')
        except ValueError:
            outcomes.append('ValueError')
    print(json.dumps({'case':'durable_replay','exit':replay.returncode,'original_receipt':json.loads(replay.stdout)==receipt,'fresh_and_conflicting':outcomes,'unchanged':state(path)==before}))
    assert outcomes == ['ValueError','ValueError'] and state(path)==before
PY"

